async function prunePublished(env,cursor){
 const page=await env.VIDEOS.list({prefix:'published/',limit:20,...(cursor?{cursor}:{})}),results=[];
 for(const entry of page.objects.filter(x=>x.key.endsWith('.meta.json'))){
  const name=entry.key.slice(10,-10);if(!NAME.test(name))continue;
  const meta=await read(env,entry.key),hash=meta?.video_sha256;
  if(!/^[a-f0-9]{64}$/.test(hash||'')){results.push({name,status:'invalid_metadata'});continue;}
  const receipt=await read(env,receiptKey(hash));
  if(receipt?.state!=='published'||receipt.video_sha256!==hash||!verifiedPublic(receipt.verification,receipt.video_id)){
   results.push({name,status:'publication_proof_missing'});continue;
  }
  const object=await env.VIDEOS.get(`published/${name}.mp4`);
  if(!object){results.push({name,status:'already_removed',video_sha256:hash});continue;}
  if(object.size>MAX_BYTES){results.push({name,status:'asset_exceeds_limit'});continue;}
  const bytes=await object.arrayBuffer();
  if(bytes.byteLength>MAX_BYTES||await digest(bytes)!==hash){results.push({name,status:'asset_hash_mismatch'});continue;}
  // The owner requested deletion of previously published media, including
  // videos later removed from YouTube. Current availability is an observation,
  // never a reason to keep a proven published backup indefinitely.
  let verification;try{verification=await youtube(env,'/youtube/verify?video_id='+encodeURIComponent(receipt.video_id));}catch{verification={ok:false,error:'current_verification_unavailable'};}
  const currentPublic=verifiedPublic(verification,receipt.video_id);
  // Persist the exact proof and hashes before the one allowed binary deletion.
  await write(env,entry.key,{...meta,publication:receipt,asset_retention:'receipt_only',retention_verification:verification,retention_observed_at:new Date().toISOString(),retention_basis:'hash_matched_historical_publication',currently_public:currentPublic});
  await env.VIDEOS.delete(`published/${name}.mp4`);
  if(await env.VIDEOS.head(`published/${name}.mp4`)){results.push({name,status:'deletion_not_confirmed'});continue;}
  results.push({name,status:'removed',absence_verified:true,currently_public:currentPublic,retention_basis:'hash_matched_historical_publication',bytes_removed:bytes.byteLength,video_sha256:hash,video_id:receipt.video_id,url:receipt.url});
 }
 return {ok:true,results,truncated:page.truncated===true,cursor:page.truncated?page.cursor:null,uploads:0,model_calls:0};
}

import {publishedProof} from '../prune-published-videos.mjs';

// The publication record is the reference. A retained local MP4 is unnecessary.
export function selectPublishedReference(entries){
 const removed=new Set(entries.filter(({data})=>data?.deleted===true&&data.absence_verified===true).map(({data})=>data.video_id));
 return entries.filter(({data})=>publishedProof(data)&&!removed.has(data.video_id))
  .sort((a,b)=>(Date.parse(b.data.verified_at||b.data.at||'')||0)-(Date.parse(a.data.verified_at||a.data.at||'')||0)||b.file.localeCompare(a.file))[0]||null;
}

 const entries=fs.readdirSync('results/publishing').filter(name=>/^youtube-.*\.json$/.test(name)).flatMap(file=>{
  try{return [{file,data:JSON.parse(fs.readFileSync('results/publishing/'+file))}];}catch{return [];}
 });
 const reference=selectPublishedReference(entries);
 if(reference){
  const {file:receiptFile,data:published}=reference;
  const response=await fetch(UPLOADER+'/youtube/verify?video_id='+encodeURIComponent(published.video_id),{redirect:'error',signal:AbortSignal.timeout(20000)});
  const verification=await response.json();
  const ok=response.ok&&verification.video_id===published.video_id&&isPublic(verification);
  report.existing_publication={source_receipt:'results/publishing/'+receiptFile,video_sha256:published.video_sha256,
   original_run_id:published.run_id,video_id:published.video_id,url:published.url,published:ok,http:response.status,
   verification,verified_at:new Date().toISOString(),new_uploads:0,local_binary_required:false};
  report.publication_observation_note='Current video availability is separate from authenticated queue ingress; original publication proof is retained.';
 }

